{
  "title": "Recent Transactions",
  "components": [
    {
      "use": "DataTable",
      "tool": "host_listTransactions",
      "params": {
        "limit": 50,
        "sort": "date_desc"
      },
      "select": "data",
      "props": {
        "caption": "Recent Account Activity",
        "searchable": true,
        "filterableBy": [
          "category",
          "status"
        ],
        "paginate": 10,
        "sortBy": "timestamp desc",
        "emptyState": "No transactions found matching your criteria.",
        "columns": [
          {
            "key": "timestamp",
            "label": "Date",
            "format": "date"
          },
          {
            "key": "merchant",
            "label": "Merchant"
          },
          {
            "key": "category",
            "label": "Category"
          },
          {
            "key": "status",
            "label": "Status"
          },
          {
            "key": "amount",
            "label": "Amount",
            "format": "money"
          }
        ]
      }
    }
  ]
}
